func loadAgent(workers int) (*ebpfPolicy, error) {
	if err := ensureRlimit(); err != nil {
		return nil, err
	}
	pinDir := pinDirectory()
	if err := ensurePinDirectory(pinDir); err != nil {
		return nil, fmt.Errorf("ensure pin directory: %w", err)
	}
	var objs ebpfutil.AgentSelectorObjects
	opts := &ebpf.CollectionOptions{
		Maps: ebpf.MapOptions{PinPath: pinDir},
	}
	if err := ebpfutil.LoadAgentSelectorObjects(&objs, opts); err != nil {
		return nil, fmt.Errorf("load agent objects: %w", err)
	}

	if workers < 0 {
		objs.Close()
		return nil, ErrInvalidConfig("workers must be non-negative")
	}

	var key uint32 = 0
	state := ebpfutil.AgentSelectorAgentState{
		Active: uint32(workers),
	}
	if objs.PebbleAgentState != nil {
		if err := objs.PebbleAgentState.Update(&key, &state, ebpf.UpdateAny); err != nil {
			objs.Close()
			return nil, fmt.Errorf("configure agent state: %w", err)
		}
	}

	return &ebpfPolicy{
		name:    "agent",
		program: objs.AgentUdpSelector,
		close:   objs.Close,
	}, nil
}

func (s *Server) openWorker(idx int) (*net.UDPConn, int, error) {
	attachPolicy := s.policy != nil && s.policy.program != nil && idx == 0
	var attachErr error

	lc := net.ListenConfig{Control: func(network, address string, c syscall.RawConn) error {
		return c.Control(func(fd uintptr) {
			if err := unix.SetsockoptInt(int(fd), unix.SOL_SOCKET, unix.SO_REUSEADDR, 1); err != nil && attachErr == nil {
				attachErr = fmt.Errorf("SO_REUSEADDR: %w", err)
				return
			}
			if err := unix.SetsockoptInt(int(fd), unix.SOL_SOCKET, unix.SO_REUSEPORT, 1); err != nil && attachErr == nil {
				attachErr = fmt.Errorf("SO_REUSEPORT: %w", err)
				return
			}
			if attachPolicy && attachErr == nil {
				if err := s.policy.attach(int(fd)); err != nil {
					attachErr = err
				}
			}
		})
	}}

	pc, err := lc.ListenPacket(context.Background(), "udp", s.cfg.ListenAddr)
	if err != nil {
		return nil, -1, err
	}
	if attachErr != nil {
		pc.Close()
		return nil, -1, attachErr
	}

	udpConn := pc.(*net.UDPConn)
	var fd int
	raw, err := udpConn.SyscallConn()
	if err != nil {
		udpConn.Close()
		return nil, -1, err
	}
	if err := raw.Control(func(value uintptr) {
		fd = int(value)
	}); err != nil {
		udpConn.Close()
		return nil, -1, err
	}

	return udpConn, fd, nil
}

